var factory = new ConnectionFactory() { HostName = "localhost" };
using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();

channel.ExchangeDeclare("app.events", ExchangeType.Topic, durable: true);

channel.QueueDeclare("order-service-queue", durable: true);
channel.QueueDeclare("alerting-queue", durable: true);
channel.QueueDeclare("global-events-queue", durable: true);

// Bind with wildcard patterns
channel.QueueBind("order-service-queue", "app.events", "order.#");
channel.QueueBind("alerting-queue",    "app.events", "*.failed");
channel.QueueBind("global-events-queue", "app.events", "#");

// Publish with a hierarchical routing key
var eventBody = Encoding.UTF8.GetBytes("Order #1234 created for US region");
channel.BasicPublish(
    exchange: "app.events",
    routingKey: "order.created.us",
    basicProperties: null,
    body: eventBody);

const amqp = require('amqplib');

async function startOrderConsumer() {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();

  await ch.assertExchange('app.events', 'topic', { durable: true });
  const { queue } = await ch.assertQueue('', { exclusive: true });

  // 'order.#' matches order.created, order.created.us, order.cancelled, etc.
  ch.bindQueue(queue, 'app.events', 'order.#');

  ch.consume(queue, (msg) => {
    if (msg.content) {
      console.log(`[${msg.fields.routingKey}] ${msg.content.toString()}`);
    }
  }, { noAck: true });

  console.log('Listening for all order events...');
}

startOrderConsumer();
